// Some portions generated by Codex
package org.eclipse.rdf4j.repository.base;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.junit.jupiter.api.Test;

class BindingTransportCapabilityTest {

	@Test
	void existingProvidersDefaultToNativeBindings() {
		RepositoryConnection connection = mock(RepositoryConnection.class, CALLS_REAL_METHODS);
		assertFalse(connection.supportsSPARQLBindingTransport());
	}

	@Test
	void nestedWrappersTrackTheCurrentDelegateCapability() {
		RepositoryConnection nativeConnection = mock(RepositoryConnection.class);
		RepositoryConnection serializedConnection = mock(RepositoryConnection.class);
		when(serializedConnection.supportsSPARQLBindingTransport()).thenReturn(true);
		RepositoryConnectionWrapper inner = new RepositoryConnectionWrapper(null, nativeConnection);
		RepositoryConnectionWrapper outer = new RepositoryConnectionWrapper(null, inner);
		assertFalse(outer.supportsSPARQLBindingTransport());
		inner.setDelegate(serializedConnection);
		assertTrue(outer.supportsSPARQLBindingTransport());
		inner.setDelegate(nativeConnection);
		assertFalse(outer.supportsSPARQLBindingTransport());
	}
}
